selector_to_html = {"a[href=\"#pyskyfire.ducts.manifold.Manifold._reserved\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.manifold.Manifold._reserved\">\n<span class=\"sig-name descname\"><span class=\"pre\">_reserved</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">name</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">n_stations</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>A boundary piece the section reserves, sized for the whole ring.</p></dd>", "a[href=\"#pyskyfire.ducts.manifold.Manifold.display_geometry\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.manifold.Manifold.display_geometry\">\n<span class=\"sig-name descname\"><span class=\"pre\">display_geometry</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">n_stations</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Branch geometry on a chosen station grid, for drawing only.</p><p>A swept manifold facets in azimuth long before it facets around its\nsection \u2013 the ring is metres round and the section centimetres \u2013 so\na smooth picture needs more stations than the area law was resolved on,\nand needing them is a drawing matter rather than a design one.</p><p>The sizes the law resolved are read between stations, and everything\nthat follows from a size is then computed at the new angles exactly:\nwhere the section sits, how it leans, and the area it ends up with. So\nthe passage drawn agrees with the resolved one at every design station\nand is interpolated only in between. <code class=\"docutils literal notranslate\"><span class=\"pre\">None</span></code> gives the resolved grid\nitself, which is what the design says and nothing more.</p></dd>", "a[href=\"#pyskyfire-ducts-manifold-manifold\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pyskyfire.ducts.manifold.Manifold<a class=\"headerlink\" href=\"#pyskyfire-ducts-manifold-manifold\" title=\"Link to this heading\">\u00b6</a></h1>", "a[href=\"#pyskyfire.ducts.manifold.Manifold._sweep_piece\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.manifold.Manifold._sweep_piece\">\n<span class=\"sig-name descname\"><span class=\"pre\">_sweep_piece</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">curve</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">n_points</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">n_stations</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Place one boundary piece of every station into machine coordinates.</p></dd>", "a[href=\"#pyskyfire.ducts.manifold.Manifold._ring\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.manifold.Manifold._ring\">\n<span class=\"sig-name descname\"><span class=\"pre\">_ring</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">n_stations</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>One branch expanded to the whole circumference.</p><p>A split manifold is its branch and that branch\u2019s mirror image, which in\nazimuth is the same arc run backwards. Nothing about the section itself\nmirrors: the plane the mirror acts in contains the machine axis, so it\ncarries each section plane onto another one and leaves the shape in it\nalone.</p></dd>", "a[href=\"../exit_cone/ExitCone.html#pyskyfire.ducts.exit_cone.ExitCone\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.exit_cone.ExitCone\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.ducts.exit_cone.</span></span><span class=\"sig-name descname\"><span class=\"pre\">ExitCone</span></span></dt><dd><p>Bases: <a class=\"reference internal\" href=\"../port/Port.html#pyskyfire.ducts.port.Port\" title=\"pyskyfire.ducts.port.Port\"><code class=\"xref py py-obj docutils literal notranslate\"><span class=\"pre\">pyskyfire.ducts.port.Port</span></code></a></p><p>How a volute\u2019s outlet duct leaves, and what it grows into.</p><p class=\"rubric\">Notes</p><p>Exit-cone geometry reaches the loss analysis three ways.\n<code class=\"xref py py-attr docutils literal notranslate\"><span class=\"pre\">final_diameter</span></code> sets station 7 and, with the arc length, the angle\nthe cone opens out at \u2013 which is most of what decides its diffusion loss.\nThe arc length also sets the wall area friction is charged over, and the\nturn sets the bend loss.</p><p>That makes <code class=\"xref py py-attr docutils literal notranslate\"><span class=\"pre\">arc_length_parameter</span></code> a real design variable rather than\na drawing detail: a longer duct opens out more gradually and recovers more\nof the velocity head, at the cost of more wetted wall and, for a given\nturn, a gentler bend. <code class=\"xref py py-meth docutils literal notranslate\"><span class=\"pre\">loss_breakdown()</span></code>\nreports the three apart so the trade can be seen.</p></dd>", "a[href=\"#pyskyfire.ducts.manifold.Manifold._place\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.manifold.Manifold._place\">\n<span class=\"sig-name descname\"><span class=\"pre\">_place</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">sizes</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">aspects</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Where each section sits, from the family or from the manifold.</p></dd>", "a[href=\"#pyskyfire.ducts.manifold.Manifold\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.manifold.Manifold\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.ducts.manifold.</span></span><span class=\"sig-name descname\"><span class=\"pre\">Manifold</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">section</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">area_law</span></span></em>, <em class=\"sig-param\"><span class=\"keyword-only-separator o\"><abbr title=\"Keyword-only parameters separator (PEP 3102)\"><span class=\"pre\">*</span></abbr></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">branches</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">2</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">rotation</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">port</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">radius</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">tilt</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">0.0</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">n_stations</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">181</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>A distributing or collecting ring, resolved from a section and a law.</p><p class=\"rubric\">Notes</p><p>Geometry is resolved on construction and carries no operating point, so one\nmanifold can be reported at several mass flows.</p></dd>", "a[href=\"#pyskyfire.ducts.manifold.Manifold._dome_shrinkage\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.manifold.Manifold._dome_shrinkage\">\n<span class=\"sig-name descname\"><span class=\"pre\">_dome_shrinkage</span></span><span class=\"sig-paren\">(</span><span class=\"sig-paren\">)</span></dt><dd><p>How fast the dome\u2019s depth falls away from the port [m/rad].</p><p>Read only when drawing a stub, which is trimmed against the port\nstation\u2019s ellipse and has to be sunk past it by whatever the neighbouring\nsections fall short. A dome that grows away from the port leaves nothing\nto make up.</p></dd>", "a[href=\"#pyskyfire.ducts.manifold.Manifold.sweep_stations\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.manifold.Manifold.sweep_stations\">\n<span class=\"sig-name descname\"><span class=\"pre\">sweep_stations</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">n_stations</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>How many stations <a class=\"reference internal\" href=\"#pyskyfire.ducts.manifold.Manifold.sweep\" title=\"pyskyfire.ducts.manifold.Manifold.sweep\"><code class=\"xref py py-meth docutils literal notranslate\"><span class=\"pre\">sweep()</span></code></a> returns on a given grid.</p><p>A split manifold sweeps both branches, so this is more than the branch\nthat was resolved has: the two meet at the dead point and share it.</p></dd>", "a[href=\"#pyskyfire.ducts.manifold.Manifold.__repr__\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.manifold.Manifold.__repr__\">\n<span class=\"sig-name descname\"><span class=\"pre\">__repr__</span></span><span class=\"sig-paren\">(</span><span class=\"sig-paren\">)</span></dt><dd></dd>", "a[href=\"#pyskyfire.ducts.manifold.Manifold._resolve_port\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.manifold.Manifold._resolve_port\">\n<span class=\"sig-name descname\"><span class=\"pre\">_resolve_port</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">port</span></span></em><span class=\"sig-paren\">)</span></dt><dd></dd>", "a[href=\"#pyskyfire.ducts.manifold.Manifold.fan_origins\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.manifold.Manifold.fan_origins\">\n<span class=\"sig-name descname\"><span class=\"pre\">fan_origins</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">n_stations</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Star-shaped fan origins for each swept station, in machine coordinates.</p><p>One per station of <a class=\"reference internal\" href=\"#pyskyfire.ducts.manifold.Manifold.sweep\" title=\"pyskyfire.ducts.manifold.Manifold.sweep\"><code class=\"xref py py-meth docutils literal notranslate\"><span class=\"pre\">sweep()</span></code></a>, so an end face can be closed off as a\nfan about a point that sees its whole boundary.</p></dd>", "a[href=\"../port/RadialPort.html#pyskyfire.ducts.port.RadialPort\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.port.RadialPort\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.ducts.port.</span></span><span class=\"sig-name descname\"><span class=\"pre\">RadialPort</span></span></dt><dd><p>Bases: <code class=\"xref py py-obj docutils literal notranslate\"><span class=\"pre\">Port</span></code></p><p>A straight stub leaving the dome a manifold\u2019s section is built on.</p><p>This is the chamber-manifold outlet. There is no swirl to take off\ntangentially, so the duct runs straight from the dome to its flange. It is\naimed from the ellipse centre \u2013 where the section\u2019s two axes cross, which\nis a defined point in a way the curved surface is not \u2013 and steered by a\nsingle angle in the section\u2019s own plane.</p><p class=\"rubric\">Notes</p><p>The angle both aims the stub and sizes it. How much room the dome leaves\nacross a tilted stub is not the ellipse\u2019s own semi-axis: it is how far the\npart of the ellipse that is actually passage boundary reaches across the\ndirection chosen, which closes down as the stub turns toward the fillets.\nThe stub stays centred on the ray it was aimed along, so a tilted one is\nsized by whichever side of it runs out of dome first; letting it shift off\nthat ray to take the room on the other side is a further freedom, not taken\nhere.</p></dd>", "a[href=\"#pyskyfire.ducts.manifold.Manifold.sweep_margins\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.manifold.Manifold.sweep_margins\">\n<span class=\"sig-name descname\"><span class=\"pre\">sweep_margins</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">n_points</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">16</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">n_stations</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>The chamber-facing wall either side of the slit [m].</p><p>Returns the two strips in the order the face is traversed, so with\n<a class=\"reference internal\" href=\"#pyskyfire.ducts.manifold.Manifold.sweep_slit\" title=\"pyskyfire.ducts.manifold.Manifold.sweep_slit\"><code class=\"xref py py-meth docutils literal notranslate\"><span class=\"pre\">sweep_slit()</span></code></a> between them they tile it without overlapping.</p></dd>", "a[href=\"../half_moon/HalfMoonSection.html#pyskyfire.ducts.half_moon.HalfMoonSection\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.half_moon.HalfMoonSection\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.ducts.half_moon.</span></span><span class=\"sig-name descname\"><span class=\"pre\">HalfMoonSection</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">profile</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">slit_height</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">fillet_radius</span></span></em>, <em class=\"sig-param\"><span class=\"keyword-only-separator o\"><abbr title=\"Keyword-only parameters separator (PEP 3102)\"><span class=\"pre\">*</span></abbr></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">slit_placement</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">0.5</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">exposure_placement</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">0.5</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">aspect_ratio</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">1.0</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">max_aspect_ratio</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Bases: <a class=\"reference internal\" href=\"../volute_section/VoluteSection.html#pyskyfire.ducts.volute_section.VoluteSection\" title=\"pyskyfire.ducts.volute_section.VoluteSection\"><code class=\"xref py py-obj docutils literal notranslate\"><span class=\"pre\">pyskyfire.ducts.volute_section.VoluteSection</span></code></a></p><p>A manifold section: chamber wall inboard, half-ellipse outboard.</p></dd>", "a[href=\"#pyskyfire.ducts.manifold.Manifold._port_frame\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.manifold.Manifold._port_frame\">\n<span class=\"sig-name descname\"><span class=\"pre\">_port_frame</span></span><span class=\"sig-paren\">(</span><span class=\"sig-paren\">)</span></dt><dd><p>Outward direction and origin of the section carrying the port.</p></dd>", "a[href=\"#pyskyfire.ducts.manifold.Manifold.sweep_slit\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.manifold.Manifold.sweep_slit\">\n<span class=\"sig-name descname\"><span class=\"pre\">sweep_slit</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">n_points</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">16</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">n_stations</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>The reserved slit swept into machine coordinates.</p><p>A strip inside the chamber-facing face, not a separate face: it is\nwhere the channels break out, and the rest of that face is metal\nagainst the wall. Drawn apart so a layout can be checked against where\nthe passes actually start and end.</p></dd>", "a[href=\"#pyskyfire.ducts.manifold.Manifold.sweep\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.manifold.Manifold.sweep\">\n<span class=\"sig-name descname\"><span class=\"pre\">sweep</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">n_points</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">64</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">n_stations</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Section boundaries swept into machine coordinates.</p><p>The machine axis is <code class=\"docutils literal notranslate\"><span class=\"pre\">z</span></code> and the dead point sits at azimuth zero. A\nsplit manifold is swept over the whole ring, both branches together, so\nwhat comes back is the closed cavity rather than half of it.</p><p><code class=\"docutils literal notranslate\"><span class=\"pre\">n_points</span></code> samples each boundary piece of the section; <code class=\"docutils literal notranslate\"><span class=\"pre\">n_stations</span></code>\nasks for a finer grid along the branch than the law was resolved on,\nfor drawing \u2013 see <a class=\"reference internal\" href=\"#pyskyfire.ducts.manifold.Manifold.display_geometry\" title=\"pyskyfire.ducts.manifold.Manifold.display_geometry\"><code class=\"xref py py-meth docutils literal notranslate\"><span class=\"pre\">display_geometry()</span></code></a>.</p></dd>", "a[href=\"#pyskyfire.ducts.manifold.Manifold.collected_velocity\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.manifold.Manifold.collected_velocity\">\n<span class=\"sig-name descname\"><span class=\"pre\">collected_velocity</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">mass_flow</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">density</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Through-flow velocity at each station of a branch [m/s].</p><p>Only the share the branch has gathered by that station is passing\nthrough it, so this is what the area there actually has to carry. A\nuniform ring ramps from nothing to its maximum at the port; a\nconstant-velocity ring holds this flat, which is the whole point of it.</p></dd>", "a[href=\"#pyskyfire.ducts.manifold.Manifold._resolve\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.manifold.Manifold._resolve\">\n<span class=\"sig-name descname\"><span class=\"pre\">_resolve</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">n_stations</span></span></em><span class=\"sig-paren\">)</span></dt><dd></dd>", "a[href=\"#pyskyfire.ducts.manifold.Manifold.sweep_port\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.manifold.Manifold.sweep_port\">\n<span class=\"sig-name descname\"><span class=\"pre\">sweep_port</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">n_points</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">64</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">n_stations</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">9</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>The port duct swept into machine coordinates.</p><p>A radial port is a plain stub, so this is the tube it cuts, trimmed back\nonto the dome it leaves rather than laid flat against it. What comes back\nis the cavity a printed part would leave for the duct, not a fairing into\nthe passage.</p></dd>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 600, interactive: false,
                onShow(instance) {MathJax.typesetPromise([instance.popper]).then(() => {});},
            });
        };
    };
    console.log("tippy tips loaded!");
};
